// Builds the watch list from the workflows themselves - no catalog to maintain.
// Every ACTIVE workflow with an enabled Schedule Trigger is watched. Its expected
// rhythm is read from the trigger: all fire times over a 400-day window are
// generated and the LARGEST gap between two runs becomes the threshold. That way
// weekday-only schedules (Mon-Fri) do not alarm on weekends.
// Workflows without a schedule (webhook, sub-workflow) are watched only if you
// give them a maxGapHours in 'overrides' (Set Configuration Values node).
const cfg = $('Set Configuration Values').first().json;
let overrides = {};
try { overrides = typeof cfg.overrides === 'object' && cfg.overrides ? cfg.overrides : JSON.parse(cfg.overrides || '{}'); }
catch (e) { throw new Error('overrides in Set Configuration Values is not valid JSON: ' + e.message); }
let ignoreRe = null;
if (cfg.ignoreNamePattern) { try { ignoreRe = new RegExp(cfg.ignoreNamePattern, 'i'); } catch (e) { throw new Error('ignoreNamePattern in Set Configuration Values is not a valid regex'); } }
const defTol = Number(cfg.defaultToleranceHours) || 2;
const retentionH = (Number(cfg.executionRetentionDays) || 14) * 24;

const H = 3600 * 1000;
const WINDOW_START = Date.UTC(2026, 0, 5, 0, 0, 0); // a Monday, 00:00 UTC
const WINDOW_END = WINDOW_START + 400 * 24 * H; // > 1 year, so monthly rhythms see their longest month

// --- minimal cron matcher: *, */n, a, a-b, a-b/n, lists; 5 or 6 fields ---
const NAMES = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, oct: 10, nov: 11, dec: 12 };
function field(spec, min, max) {
  const set = new Set();
  for (const part of String(spec).toLowerCase().split(',')) {
    const m = part.match(/^(\*|[a-z0-9]+(?:-[a-z0-9]+)?)(?:\/(\d+))?$/);
    if (!m) return null;
    const step = m[2] ? parseInt(m[2], 10) : 1;
    let lo = min, hi = max;
    if (m[1] !== '*') {
      const [a, b] = m[1].split('-').map(x => (NAMES[x] !== undefined ? NAMES[x] : parseInt(x, 10)));
      if (isNaN(a) || (b !== undefined && isNaN(b))) return null;
      lo = a; hi = b !== undefined ? b : (m[2] ? max : a);
    }
    for (let v = lo; v <= hi; v += step) set.add(v);
  }
  return set;
}
function cronTimes(expr) {
  let p = String(expr || '').trim().split(/\s+/);
  if (p.length === 5) p = ['0'].concat(p);
  if (p.length !== 6) return null;
  const mi = field(p[1], 0, 59), ho = field(p[2], 0, 23), dom = field(p[3], 1, 31), mo = field(p[4], 1, 12), dow = field(p[5], 0, 7);
  if (!mi || !ho || !dom || !mo || !dow) return null;
  if (dow.has(7)) dow.add(0);
  const domAny = p[3] === '*' || p[3] === '?', dowAny = p[5] === '*' || p[5] === '?';
  const out = [];
  for (let day = WINDOW_START; day < WINDOW_END; day += 24 * H) {
    const d = new Date(day);
    if (!mo.has(d.getUTCMonth() + 1)) continue;
    const dm = dom.has(d.getUTCDate()), dw = dow.has(d.getUTCDay());
    const dayOk = domAny && dowAny ? true : domAny ? dw : dowAny ? dm : (dm || dw);
    if (!dayOk) continue;
    for (const hh of ho) { if (hh > 23) continue; for (const mm of mi) { if (mm < 60) out.push(day + (hh * 60 + mm) * 60000); } }
  }
  return out;
}
function every(stepMs, offsetMs) { const out = []; for (let t = WINDOW_START + (offsetMs || 0); t < WINDOW_END; t += stepMs) out.push(t); return out; }
// Fire times of one Schedule Trigger rule entry (UTC; timezone shifts do not change gaps)
function ruleTimes(r) {
  const f = r.field || 'days';
  if (f === 'cronExpression') return cronTimes(r.expression);
  if (f === 'seconds') return every(60000);
  if (f === 'minutes') return every((Number(r.minutesInterval) || 5) * 60000);
  if (f === 'hours') return every((Number(r.hoursInterval) || 1) * H, (Number(r.triggerAtMinute) || 0) * 60000);
  if (f === 'days') return every((Number(r.daysInterval) || 1) * 24 * H, ((Number(r.triggerAtHour) || 0) * 60 + (Number(r.triggerAtMinute) || 0)) * 60000);
  if (f === 'weeks') {
    const days = (Array.isArray(r.triggerAtDay) && r.triggerAtDay.length ? r.triggerAtDay : [0]).map(Number);
    const n = Number(r.weeksInterval) || 1; const out = [];
    for (let t = WINDOW_START; t < WINDOW_END; t += 24 * H) {
      const d = new Date(t); const week = Math.floor((t - WINDOW_START) / (7 * 24 * H));
      if (week % n === 0 && days.indexOf(d.getUTCDay()) !== -1) out.push(t + ((Number(r.triggerAtHour) || 0) * 60 + (Number(r.triggerAtMinute) || 0)) * 60000);
    }
    return out;
  }
  if (f === 'months') {
    const n = Number(r.monthsInterval) || 1; const dom = Number(r.triggerAtDayOfMonth) || 1; const out = [];
    for (let i = 0; i < 14; i += n) out.push(Date.UTC(2026, i, dom, Number(r.triggerAtHour) || 0, Number(r.triggerAtMinute) || 0));
    return out;
  }
  return null;
}
function maxGapHours(times) {
  if (!times || times.length < 2) return null;
  times.sort((a, b) => a - b);
  let g = 0; for (let i = 1; i < times.length; i++) g = Math.max(g, times[i] - times[i - 1]);
  return Math.round(g / H * 100) / 100;
}

const watch = [];
const skipped = [];
for (const it of $input.all()) {
  const wf = it.json;
  if (!wf || !wf.id || !wf.active) continue;
  const ov = overrides[wf.id] || overrides[wf.name] || {};
  if (ov.ignore === true || (ignoreRe && ignoreRe.test(wf.name || ''))) { skipped.push(wf.name + ' (ignored by configuration)'); continue; }
  const triggers = (wf.nodes || []).filter(n => n.type === 'n8n-nodes-base.scheduleTrigger' && !n.disabled);
  let gap = null; let source = '';
  if (Number(ov.maxGapHours) > 0) { gap = Number(ov.maxGapHours); source = 'override'; }
  else if (triggers.length) {
    let all = []; let unreadable = false;
    for (const t of triggers) for (const r of (((t.parameters || {}).rule || {}).interval || [{}])) {
      const times = ruleTimes(r); if (times === null) unreadable = true; else all = all.concat(times);
    }
    gap = maxGapHours(all); source = 'schedule';
    if (unreadable || gap === null) { skipped.push(wf.name + ' (schedule not readable - set maxGapHours in overrides)'); continue; }
  } else continue; // no schedule, no override: not watched
  const tol = Number(ov.toleranceHours) > 0 ? Number(ov.toleranceHours) : Math.max(defTol, Math.round(gap * 0.1 * 100) / 100);
  const saveNone = (wf.settings || {}).saveDataSuccessExecution === 'none';
  if (saveNone) { skipped.push(wf.name + ' (saveDataSuccessExecution = none, successful runs are not stored)'); continue; }
  if (gap + tol > retentionH) { skipped.push(wf.name + ' (expected gap ' + gap + 'h + ' + tol + 'h is longer than the execution retention of ' + retentionH + 'h)'); continue; }
  watch.push({ id: wf.id, name: wf.name, maxGapHours: gap, toleranceHours: tol, source, createdAt: wf.createdAt || null });
}
const sd = $getWorkflowStaticData('global');
sd.skipped = skipped; // read by the check node; avoids carrying it through the fetch
return watch.map(w => ({ json: Object.assign({}, w, { skippedCount: skipped.length }) }));

// Evaluates the executions per watched workflow. Manual test runs never count.
// Findings: OVERDUE (no productive success within expected gap + tolerance),
// NO_SUCCESS (none in the retention window), ERROR_RATE (last 7 days), SLOW
// (latest successful run > 3x median and > minSlowSeconds).
const cfg = $('Set Configuration Values').first().json;
const rateLimit = Number(cfg.errorRateThreshold) || 0.2;
const minSlow = Number(cfg.minSlowSeconds) || 60;
const H = 3600 * 1000;
const now = Date.now();
const watch = $('Build Watch List from Schedules').all().map(i => i.json);
const byWf = {};
for (const it of $input.all()) {
  const e = it.json;
  if (!e || !e.workflowId) continue; // empty placeholder item when nothing was found
  (byWf[e.workflowId] = byWf[e.workflowId] || []).push(e);
}
const fmt = (t) => new Date(t).toISOString().replace('T', ' ').substring(0, 16) + ' UTC';
const findings = [];
for (const w of watch) {
  const execs = (byWf[w.id] || []).filter(e => e.mode !== 'manual').sort((a, b) => new Date(b.startedAt) - new Date(a.startedAt));
  const ok = execs.filter(e => e.status === 'success');
  const limitH = w.maxGapHours + w.toleranceHours;
  if (!ok.length) {
    const age = w.createdAt ? (now - new Date(w.createdAt)) / H : Infinity;
    if (age > Math.max(3 * w.maxGapHours, 48)) findings.push({ sev: 'ERROR', name: w.name, id: w.id, type: 'NO_SUCCESS', msg: 'No productive successful run in the stored executions. Expected at least every ' + w.maxGapHours + 'h.' });
  } else {
    const last = new Date(ok[0].startedAt).getTime();
    const ageH = (now - last) / H;
    if (ageH > limitH) findings.push({ sev: 'ERROR', name: w.name, id: w.id, type: 'OVERDUE', msg: 'Last successful run ' + fmt(last) + ' (' + Math.round(ageH) + 'h ago). Expected at least every ' + w.maxGapHours + 'h + ' + w.toleranceHours + 'h tolerance.' });
  }
  const recent = execs.filter(e => now - new Date(e.startedAt) < 7 * 24 * H);
  if (recent.length >= 5) {
    const errs = recent.filter(e => e.status === 'error' || e.status === 'crashed');
    const fresh = errs.some(e => now - new Date(e.startedAt) < 24 * H);
    const rate = errs.length / recent.length;
    if (rate > rateLimit && fresh) findings.push({ sev: 'ERROR', name: w.name, id: w.id, type: 'ERROR_RATE', msg: errs.length + ' of ' + recent.length + ' runs failed in the last 7 days (' + Math.round(rate * 100) + '%), at least one in the last 24h.' + (execs.length >= 50 ? ' (Only the last 50 runs were loaded.)' : '') });
  }
  const dur = ok.slice(0, 10).map(e => (new Date(e.stoppedAt) - new Date(e.startedAt)) / 1000).filter(d => d > 0 && isFinite(d));
  if (dur.length >= 5 && now - new Date(ok[0].startedAt) < 24 * H) {
    const med = dur.slice().sort((a, b) => a - b)[Math.floor(dur.length / 2)];
    if (dur[0] > 3 * med && dur[0] > minSlow) findings.push({ sev: 'WARN', name: w.name, id: w.id, type: 'SLOW', msg: 'Latest run took ' + dur[0].toFixed(0) + 's, median of the last runs is ' + med.toFixed(0) + 's.' });
  }
}
findings.sort((a, b) => (a.sev === b.sev ? 0 : a.sev === 'ERROR' ? -1 : 1));
const skipped = $getWorkflowStaticData('global').skipped || [];
const esc = (t) => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = findings.map(f => '<tr><td>' + esc(f.sev) + '</td><td>' + esc(f.name) + '<br><small>' + esc(f.id) + '</small></td><td>' + esc(f.type) + '</td><td>' + esc(f.msg) + '</td></tr>').join('');
const errCount = findings.filter(f => f.sev === 'ERROR').length;
const subject = '[n8n] Liveness: ' + errCount + ' error(s), ' + (findings.length - errCount) + ' warning(s)';
const html = '<p><b>' + findings.length + ' finding(s)</b> across ' + watch.length + ' watched workflows.</p>'
  + '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">'
  + '<tr><th>Level</th><th>Workflow</th><th>Check</th><th>Detail</th></tr>' + rows + '</table>'
  + (skipped.length ? '<p style="font-size:12px;color:#666"><b>Not assessed (' + skipped.length + '):</b><br>' + skipped.map(esc).join('<br>') + '</p>' : '');
return [{ json: { hasFindings: findings.length > 0, count: findings.length, errors: errCount, watched: watch.length, findings, skipped, subject, html, ts: new Date(now).toISOString() } }];
